function isPlainObject(v) {
  return v && typeof v === "object" && !Array.isArray(v);
}

function merge(a, b) {
  if (!isPlainObject(a) || !isPlainObject(b)) return b ?? a;
  const out = { ...a };
  for (const k of Object.keys(b)) {
    out[k] = isPlainObject(a[k]) && isPlainObject(b[k])
      ? merge(a[k], b[k])
      : b[k];
  }
  return out;
}

module.exports = { merge };
